INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 18, 'theory', 'Quiz: final project');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 18, 0, 'Where does the design of a service begin?', '["With choosing technologies", "With requirements and numbers: functions, load, volume, SLO, budget", "With buying servers", "With writing code"]', 1, 'The numbers determine which building blocks are needed; without them the diagram is built blind.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 18, 1, 'Why is video in the project served through a CDN and object storage rather than through application servers?', '["That''s just the convention", "Otherwise no fleet of servers and no traffic bill would be enough; storage and a CDN are cheaper and built for this", "Servers cannot read files", "A CDN encrypts video"]', 1, 'Application servers handle metadata and signed links, while the CDN delivers the bytes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 18, 2, 'Why is video transcoding done asynchronously through a queue?', '["To slow down the upload", "The task is heavy and long: a queue smooths peaks and lets you scale workers and run them on spot instances", "It makes the code easier to write", "To save on the CDN"]', 1, 'The user gets a confirmation right away; the workers are idempotent and scale with the backlog.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 18, 3, 'How is the feed built in the final project?', '["Pull only", "Push only", "A hybrid: fan-out for ordinary authors and mixing in celebrities at read time", "Randomly"]', 2, 'The hybrid solves the celebrity problem and keeps writes cheap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 18, 4, 'What is evaluated in an answer to a system design problem?', '["The number of technologies named", "The chain of reasoning: requirements, numbers, bottlenecks, failures, and trade-offs", "Drawing speed", "The one correct diagram"]', 1, 'What matters is showing how you reason and how you change the solution when requirements change.');
